```java
URL build() {
    try {
        // Create a new URI using the original URL's components
        URI uri = new URI(
            u.getProtocol(),
            u.getUserInfo(),
            IDN.toASCII(u.getHost()), // puny-code the host
            u.getPort(),
            null, // leave path null to avoid encoding
