                sb.append('?');
                appendToAscii(StringUtil.releaseBuilder(q), true, sb);
            }
            if (u.getRef() != null) {
                sb.append('#');
                appendToAscii(u.getRef(), false, sb);
            }
            normUrl = sb.toString();
        }

        u = new URL(normUrl);
        return u;
    } catch (MalformedURLException | URISyntaxException | UnsupportedEncodingException e) {
        assert Validate.assertFail(e.toString());
        return u;
