        }
    }

    if (index < values.length && !values[index].isEmpty()) {
        int wifiCount = Integer.parseInt(values[index++]);

        for (int i = 0; i < wifiCount; i++) {
            index += 1; // wifi name
            String macAddress = values[index++];
